from produire import produire,paras,table,steps
from medicaments_suite import willebrand
produire(7,[
('La maladie de von Willebrand résulte d’un déficit quantitatif ou qualitatif du facteur de von Willebrand. Les {formes de la maladie} ont des conséquences diagnostiques et thérapeutiques différentes.',paras('Ce facteur participe à l’adhésion des plaquettes et protège le facteur VIII dans la circulation. Son anomalie favorise principalement les saignements cutanéomuqueux.', 'Les formes quantitatives et qualitatives doivent être distinguées en consultation d’hémostase. Le type 3, rare et sévère, comporte un déficit majeur et peut aussi provoquer des hémorragies profondes.')),
('La maladie touche les deux sexes. Les {circonstances de découverte} comprennent les saignements spontanés et ceux provoqués par un geste.',paras('Épistaxis récidivantes, règles abondantes, saignement dentaire ou postopératoire peuvent conduire au diagnostic. Les symptômes varient d’une personne à l’autre et l’histoire familiale peut être discrète ou méconnue.', 'Les HUG décrivent cette maladie héréditaire avec des formes de sévérité différente. Le risque d’un geste invasif ne se déduit pas d’un simple classement de fréquence ni du seul sexe du patient.')),
('L’atteinte combine un défaut d’hémostase primaire et parfois une baisse du facteur VIII. Les {mécanismes utiles} expliquent les limites du bilan courant.',paras('Une anomalie d’adhésion plaquettaire favorise saignements du nez, de la bouche et des muqueuses. La baisse associée du facteur VIII peut devenir importante dans les formes sévères.', 'Un examen standard de coagulation ne caractérise pas l’activité du facteur de von Willebrand. Les dosages spécifiques sont nécessaires lorsque l’histoire clinique est évocatrice.')),
('Un saignement grave se traite avant la fin du typage. Les {situations prioritaires} nécessitent une coordination urgente avec l’hémostase.',table(['🚩 Constat','Conduite'],[['Épistaxis incontrôlée, malaise ou retentissement important.','Hémostase locale et prise en charge hospitalière adaptées.'],['Symptôme neurologique ou suspicion d’hémorragie profonde.','Évaluation urgente, notamment dans une forme sévère.'],['Geste invasif imminent sans plan hémostatique.','Contacter le centre avant l’acte si la situation le permet.'],['Grossesse, accouchement ou saignement tardif du post-partum.','Coordonner obstétrique et hématologie sans banaliser le risque.']])) ,
('L’histoire hémorragique personnelle et familiale est déterminante. Les {questions structurées} mettent en évidence des épisodes parfois considérés comme habituels.',paras('Demander fréquence et durée des épistaxis, ecchymoses, gingivorragies, règles abondantes et saignements après soins dentaires, chirurgie ou accouchement. Préciser les besoins antérieurs en fer, transfusion ou traitement hémostatique.', 'Rechercher diagnostic familial, carte de maladie, type connu et réponse documentée à la desmopressine. Relever les médicaments qui augmentent le risque de saignement et les interventions prévues.')),
('L’examen évalue le saignement actuel et son retentissement. Les {signes à rechercher} complètent l’histoire sans permettre à eux seuls de typer la maladie.',paras('Examiner le point nasal, la bouche et la peau, puis rechercher pâleur et signes de mauvaise tolérance. Une maladie hémorragique connue ne dispense pas de chercher une lésion locale.', 'Adapter l’examen aux douleurs profondes ou articulaires et aux manifestations neurologiques. Un examen normal entre deux épisodes n’exclut pas une maladie hémorragique.')),
('Le syndrome cutanéomuqueux peut avoir plusieurs origines. Les {éléments comparatifs} aident à organiser le bilan.',table(['Tableau','Orientation'],[['Saignements muqueux anciens, histoire familiale compatible.','Maladie de von Willebrand à rechercher.'],['Thrombopénie isolée importante.','PTI ou autre cause plaquettaire à explorer.'],['Télangiectasies et épistaxis familiales.','Rendu-Osler à envisager.'],['Saignement récent sous médicament.','Effet pharmacologique possible, sans exclure une maladie associée.'],['Récidive strictement unilatérale avec obstruction.','Rechercher également une lésion nasale.']])) ,
('Le diagnostic associe histoire hémorragique et dosages spécialisés. Les {principes de confirmation} évitent une exclusion sur un bilan trop limité.',paras('Doser l’antigène et l’activité du facteur de von Willebrand ainsi que l’activité du facteur VIII ; compléter par une numération plaquettaire. Une anomalie nécessite confirmation et typage dans un centre d’hémostase.', 'L’absence de diagnostic familial ou un bilan courant rassurant ne suffisent pas à exclure la maladie. Le centre interprète le contexte du prélèvement et décide des examens complémentaires ou répétés.')),
('Les examens déterminent le type et préparent le traitement. Les {étapes spécialisées} répondent à des questions distinctes.',paras('9.a — Référence : évaluation clinique et biologique spécialisée du complexe facteur de von Willebrand/facteur VIII.', '9.b — Hémogramme, antigène et activité du facteur de von Willebrand, facteur VIII ; bilan du retentissement et du fer selon les pertes.', '9.c — Examens de caractérisation et confirmation selon les premiers résultats, sous la responsabilité du laboratoire d’hémostase. Le type de maladie doit être consigné clairement.', '9.d — Si une desmopressine est envisagée, documenter la réponse et la sécurité selon le centre. Un résultat biologique isolé ne remplace pas un plan pour l’épisode hémorragique ou l’intervention.')),
('L’{algorithme Willebrand} relie le type de maladie à la gravité du saignement. Le traitement antérieurement efficace doit être documenté, sans supposer qu’il convient toujours.',steps('Évaluer urgence et contrôler la source nasale.', 'Rechercher carte, type, traitements et réponse connus ; joindre le centre.', 'Si maladie non diagnostiquée → bilan spécifique sans retarder les soins urgents.', 'Choisir mesures locales, antifibrinolytique, desmopressine ou concentré selon indication, type et contre-indications.', 'Contrôler efficacité, tolérance et plan de suivi, notamment autour des gestes invasifs.')),
('Le traitement est individualisé avec un centre d’hémostase. Les {produits suisses et leurs limites} empêchent de traiter toutes les formes de la même manière.',paras('11.A — Obtenir une hémostase sûre, traiter les pertes et prévenir les complications des gestes. Préférer des soins nasaux qui limitent les lésions supplémentaires.', '11.B — L’acide tranexamique peut contribuer au contrôle des saignements muqueux dans les situations adaptées. La desmopressine convient à certaines formes répondantes ; un concentré est nécessaire si elle est inefficace ou contre-indiquée, selon la gravité.', '@@MEDICAMENTS@@', 'Le type 2B est une contre-indication d’Octostim dans l’AIPS ; le type 3 ne répond pas à ce mécanisme de libération. Ne pas essayer empiriquement la desmopressine sur la seule présence d’une épistaxis.', '11.C — Surveiller réponse clinique et facteurs selon le produit ; pour la desmopressine, surveiller aussi équilibre hydrique et sodium. Pour les concentrés combinés, éviter une élévation excessive du facteur VIII et rechercher des inhibiteurs si la réponse attendue manque.', '11.D — Fournir une carte et un plan écrit : type, réponse aux traitements, conduite en cas d’hémorragie et contact du centre. Préparer soins dentaires, chirurgie, grossesse et post-partum ; corriger une carence martiale selon son bilan.')),
('La prévention repose sur l’anticipation des situations hémorragiques. Les {mesures successives} concernent également les proches et les prescripteurs.',paras('Primaire : informer les soignants avant un acte et revoir les médicaments aggravant l’hémorragie. Secondaire : reconnaître les pertes répétées et rechercher une carence en fer, même si elles paraissent habituelles. Tertiaire : conserver le plan hémostatique, organiser le suivi spécialisé et proposer une évaluation familiale appropriée.')),
('La maladie concerne les deux sexes et surtout les saignements muqueux. Le diagnostic exige des dosages spécifiques. La desmopressine n’est pas adaptée à toutes les formes. La carte de maladie et le plan avant une intervention sont essentiels.', '')
],[('Le facteur de von Willebrand n’agit-il que sur le facteur VIII ?','Non : il participe aussi à l’adhésion des plaquettes.'),('La maladie concerne-t-elle uniquement les hommes ?','Non : elle touche les deux sexes.'),('Des règles abondantes peuvent-elles révéler la maladie ?','Oui : elles font partie de l’histoire hémorragique à rechercher.'),('L’absence d’histoire familiale suffit-elle à exclure le diagnostic ?','Non : une histoire familiale peut être absente ou méconnue.'),('Un bilan standard de coagulation suffit-il ?','Non : des dosages spécifiques sont nécessaires.'),('Quels dosages sont fondamentaux ?','Antigène et activité du facteur de von Willebrand, activité du facteur VIII, avec numération plaquettaire.'),('Le type 3 peut-il provoquer des hémorragies profondes ?','Oui : il s’agit d’une forme particulièrement sévère.'),('Faut-il attendre le typage complet pour traiter une hémorragie grave ?','Non : les soins urgents et la coordination spécialisée débutent immédiatement.'),('La desmopressine convient-elle au type 2B ?','Non : ce type figure dans les contre-indications d’Octostim.'),('Pourquoi surveiller le sodium sous desmopressine ?','La rétention d’eau peut entraîner une hyponatrémie grave.'),('Les doses injectables se transposent-elles à la forme nasale ?','Non : chaque formulation possède ses propres instructions.'),('Les unités de von Willebrand et de facteur VIII sont-elles interchangeables ?','Non : le calcul doit utiliser le facteur visé.'),('Une maladie connue exclut-elle une lésion nasale associée ?','Non : la source locale du saignement reste à examiner.'),('Le suivi hémorragique s’arrête-t-il à l’accouchement ?','Non : des saignements tardifs du post-partum sont possibles.')],(3,11,13,25,26),willebrand)
